if (!int.TryParse((Console.ReadLine() ?? "").Trim(), out var count) || count < 1 || count > 50) Environment.Exit(1);
var names = new string[count];
for (var i = 0; i < count; i++)
{
    var name = (Console.ReadLine() ?? "").Trim();
    if (name.Length == 0 || name.Contains(' ')) Environment.Exit(1);
    names[i] = name;
}
if (!int.TryParse((Console.ReadLine() ?? "").Trim(), out var queries) || queries < 1 || queries > 20) Environment.Exit(1);
var book = new PhoneBook(names);
for (var i = 0; i < queries; i++)
{
    if (!int.TryParse((Console.ReadLine() ?? "").Trim(), out var index)) Environment.Exit(1);
    try
    {
        Console.WriteLine("name=" + book[index]);
    }
    catch (IndexOutOfRangeException)
    {
        Console.WriteLine("out-of-range");
    }
}

sealed class PhoneBook
{
    private readonly string[] _names;

    public int Count => _names.Length;

    public PhoneBook(string[] names)
    {
        _names = new string[names.Length];
        Array.Copy(names, _names, names.Length);
    }

    public string this[int index] =>
        index >= 0 && index < Count ? _names[index] : throw new IndexOutOfRangeException();
}
